void add_suggestion_to_scene(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    // Create UI components
    UiElement* icon = ui_element_create("icon");
    UiElement* content_text = ui_element_create("content_text");
    UiElement* description_text = ui_element_create("description_text");

    // Bind UI elements to model
    ui_element_bind(icon, model, "icon_data");
    ui_element_bind(content_text, model, "content");
    ui_element_bind(description_text, model, "description");

    // Create layout and add elements
    UiElement* layout = ui_layout_create(UI_LAYOUT_VERTICAL);
    ui_layout_add_child(layout, icon);
    ui_layout_add_child(layout, content_text);
    ui_layout_add_child(layout, description_text);

    // Create background button for navigation
    UiElement* background_button = ui_button_create();
    ui_button_set_on_click(background_button, (void (*)(void*))UiBrowserInterface_navigate, browser);
    ui_element_bind(background_button, model, "button_color");

    // Add background button to layout
    ui_layout_add_child(layout, background_button);

    // Set binding to manage UI updates
    suggestion_binding_set(element_binding, layout, model);

    // Add the suggestion to the scene
    ui_scene_add_element(scene, layout);
}

void add_suggestion_element(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    // Create and configure the background button
    UiElement* background_button = create_button_element();
    set_button_color(background_button, &model->background_color);
    set_button_click_handler(background_button, (void*)browser->navigate_to_suggestion, browser);

    // Create and configure the icon element
    UiElement* icon = create_image_element();
    bind_image_to_model(icon, model, "icon_path");
    set_element_position(icon, 10, 10);

    // Create and configure content text element
    UiElement* content_text = create_text_element();
    bind_text_to_model(content_text, model, "content_text");
    set_element_position(content_text, 50, 10);

    // Create and configure description text element
    UiElement* description_text = create_text_element();
    bind_text_to_model(description_text, model, "description_text");
    set_element_position(description_text, 50, 40);

    // Create layout and add all components
    UiElement* layout = create_layout_element(LAYOUT_VERTICAL);
    add_child(layout, icon);
    add_child(layout, content_text);
    add_child(layout, description_text);

    // Bind layout to the suggestion binding object
    bind_element_to_binding(layout, element_binding);

    // Add the background button and layout to the scene
    add_child(background_button, layout);
    add_element_to_scene(scene, background_button);
}

void create_and_add_suggestion_element(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    // Create UI components (icon, text fields, etc.)
    UiElement* icon = create_ui_element("icon");
    UiElement* content_text = create_ui_element("content_text");
    UiElement* description_text = create_ui_element("description_text");

    // Bind UI elements to the model
    bind_element_property(icon, "image", model, "suggestion_icon");
    bind_element_property(content_text, "text", model, "suggestion_content");
    bind_element_property(description_text, "text", model, "suggestion_description");

    // Create a layout to hold the UI components
    UiElement* layout = create_ui_element("layout");
    add_child(layout, icon);
    add_child(layout, content_text);
    add_child(layout, description_text);

    // Create a background button with navigation action
    UiElement* background_button = create_ui_element("button");
    bind_element_property(background_button, "background_color", model, "suggestion_background_color");
    bind_element_property(background_button, "hover_color", model, "suggestion_hover_color");
    set_element_event_handler(background_button, "click", (void*)browser, navigate_to_suggestion);

    // Add the layout as a child of the background button
    add_child(background_button, layout);

    // Set up the binding object for managing UI updates
    setup_suggestion_binding(element_binding, background_button, model);

    // Add the constructed suggestion element to the scene
    add_element_to_scene(scene, background_button);
}

void add_suggestion_element(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    // Construct UI layout
    UiElement* layout = create_layout(UI_LAYOUT_VERTICAL);

    // Create icon element and bind it to the model
    UiElement* icon = create_icon_element(model, "icon_property");
    add_child(layout, icon);

    // Create content text element and bind it to the model
    UiElement* content_text = create_text_element(model, "content_property");
    add_child(layout, content_text);

    // Create description text element and bind it to the model
    UiElement* description_text = create_text_element(model, "description_property");
    add_child(layout, description_text);

    // Create background button that triggers navigation on click
    UiElement* background_button = create_button_element();
    set_on_click(background_button, (void (*)(void*))navigate_to_suggestion, browser);

    // Bind button colors to model
    bind_color(background_button, "background_color_property");

    // Add the background button to the layout
    add_child(layout, background_button);

    // Set the binding object for managing UI updates
    set_binding(layout, element_binding);

    // Add the suggestion element to the scene
    add_element_to_scene(scene, layout);
}

void create_suggestion_element(UiScene* scene, UiBrowserInterface* browser, Model* model, SuggestionBinding* element_binding) {
    UiElement* suggestion_element = ui_element_create();
    UiElement* layout = ui_layout_create(HORIZONTAL);

    // Create and bind icon
    UiElement* icon = ui_image_create();
    model_bind(model, "icon", icon, UI_PROPERTY_IMAGE);
    ui_element_add_child(layout, icon);

    // Create and bind content text
    UiElement* content = ui_text_create();
    model_bind(model, "content", content, UI_PROPERTY_TEXT);
    ui_element_add_child(layout, content);

    // Create and bind description text
    UiElement* description = ui_text_create();
    model_bind(model, "description", description, UI_PROPERTY_TEXT);
    ui_element_add_child(layout, description);

    // Create background button and bind click action
    UiElement* background_button = ui_button_create();
    ui_button_set_on_click(background_button, (UiOnClickCallback)ui_browser_interface_navigate, browser);
    model_bind(model, "background_color", background_button, UI_PROPERTY_COLOR);
    model_bind(model, "hover_color", background_button, UI_PROPERTY_HOVER_COLOR);

    // Add layout to the background button
    ui_element_add_child(background_button, layout);

    // Add background button to the suggestion element
    ui_element_add_child(suggestion_element, background_button);

    // Add the suggestion element to the scene
    ui_scene_add_element(scene, suggestion_element);

    // Setup binding for UI updates
    suggestion_binding->element = suggestion_element;
    suggestion_binding->model = model;
}
